static struct page_pool * cpsw_create_page_pool ( struct cpsw_common * cpsw , int size ) { struct page_pool_params pp_params = { } ; struct page_pool * pool ; pp_params . order = 0 ; pp_params . flags = PP_FLAG_DMA_MAP ; pp_params . pool_size = size ; pp_params . nid = NUMA_NO_NODE ; pp_params . dma_dir = DMA_BIDIRECTIONAL ; pp_params . dev = cpsw -> dev ; if ( IS_ERR ( pool ) ) { dev_err ( cpsw -> dev , "cannot create rx page pool\n" ) ; } return pool ; } 